#include "frozen_prefix.hpp"
using Q=mpq_class;using Vec=std::array<I,4>;using Mat=std::array<Vec,4>;using QVec=std::array<Q,4>;
I imod(I a,const I&p){a%=p;if(a<0)a+=p;return a;}
I nearest(const Q&q){I num=2*q.get_num()+q.get_den(),den=2*q.get_den();return fd(num,den);}
struct GS{std::array<QVec,4>s{};std::array<std::array<Q,4>,4>mu{};std::array<Q,4>norm{};};
GS gram(const Mat&B){GS g;for(int i=0;i<4;i++){for(int t=0;t<4;t++)g.s[i][t]=Q(B[i][t]);for(int j=0;j<i;j++){need(g.norm[j]>0,"nonzero GS pivot");Q dot=0;for(int t=0;t<4;t++)dot+=Q(B[i][t])*g.s[j][t];g.mu[i][j]=dot/g.norm[j];for(int t=0;t<4;t++)g.s[i][t]-=g.mu[i][j]*g.s[j][t];}for(int t=0;t<4;t++)g.norm[i]+=g.s[i][t]*g.s[i][t];}return g;}
bool lll(Mat&B,unsigned&steps){int k=1;GS g=gram(B);while(k<4&&steps<1024){steps++;for(int j=k-1;j>=0;j--){I z=nearest(g.mu[k][j]);if(z!=0){for(int t=0;t<4;t++)B[k][t]-=z*B[j][t];g=gram(B);}}if(g.norm[k]>=(Q(3,4)-g.mu[k][k-1]*g.mu[k][k-1])*g.norm[k-1])k++;else{std::swap(B[k],B[k-1]);g=gram(B);k=std::max(1,k-1);}}return k==4;}
struct Sep{bool closed=false,reduced=false;Vec y{},lo{},hi{};I C,min,max,ql,qh;unsigned steps=0;};
Sep screen(const I&p,const Quad&t,const Quad&u,const I&M){Sep out;out.lo={0,0,0,0};out.hi={I(3*M),I(9*M*M),I(3*M*M),I(M*M*M)};Vec w;for(int j=0;j<4;j++)w[j]=out.hi[j]-out.lo[j]+1;Mat B{{Vec{p,0,0,0},Vec{0,p,0,0},Vec{-t[1],-t[0],1,0},Vec{-u[1],-u[0],0,1}}};for(auto&row:B)for(int j=0;j<4;j++)row[j]*=w[j];out.reduced=lll(B,out.steps);if(!out.reduced)return out;
for(unsigned code=1;code<81;code++){unsigned c=code;Vec weighted{};bool any=false;for(int k=0;k<4;k++){int z=int(c%3)-1;c/=3;any|=z!=0;for(int j=0;j<4;j++)weighted[j]+=z*B[k][j];}if(!any)continue;Vec y;for(int j=0;j<4;j++){need(weighted[j]%w[j]==0,"exact integer unscale");y[j]=weighted[j]/w[j];}need(imod(y[0]+t[1]*y[2]+u[1]*y[3],p)==0&&imod(y[1]+t[0]*y[2]+u[0]*y[3],p)==0,"independent dual congruence");I low=0,high=0;for(int j=0;j<4;j++){if(y[j]>=0){low+=y[j]*out.lo[j];high+=y[j]*out.hi[j];}else{low+=y[j]*out.hi[j];high+=y[j]*out.lo[j];}}I C=imod(y[2]*t[2]+y[3]*u[2],p),ql=cd(low-C,p),qh=fd(high-C,p);if(ql>qh){out.closed=true;out.y=y;out.C=C;out.min=low;out.max=high;out.ql=ql;out.qh=qh;return out;}}
return out;}
void ivec(std::ostream&o,const Vec&v){o<<'[';for(int j=0;j<4;j++){if(j)o<<',';o<<'"'<<v[j]<<'"';}o<<']';}
void quad(std::ostream&o,const Quad&v){o<<'[';for(int j=0;j<3;j++){if(j)o<<',';o<<'"'<<v[j]<<'"';}o<<']';}
void emitcert(std::ostream&o,const I&p,const Quad&t,const Quad&u,const I&M,const Sep&s){o<<"{\"p\":\""<<p<<"\",\"M\":\""<<M<<"\",\"T\":";quad(o,t);o<<",\"U\":";quad(o,u);o<<",\"vector\":";ivec(o,s.y);o<<",\"lo\":";ivec(o,s.lo);o<<",\"hi\":";ivec(o,s.hi);o<<",\"constant\":\""<<s.C<<"\",\"minimum\":\""<<s.min<<"\",\"maximum\":\""<<s.max<<"\",\"quotient_low\":\""<<s.ql<<"\",\"quotient_high\":\""<<s.qh<<"\"}";}
void controls(const std::string&id){unsigned maps=0,closed=0,positive=0;uint64_t tuples=0,roots=0;std::ostringstream certs;bool comma=false;for(long p:{5L,7L,11L,13L,19L})for(long M:{1L,2L})for(long k=0;k<24;k++){Quad t{I((3*k+1)%p),I((5*k+2)%p),I((7*k+3)%p)},u{I((11*k+4)%p),I((13*k+5)%p),I((17*k+6)%p)};if(k==0)t=u=Quad{0,0,0};if(k==23)t=u=Quad{0,0,I(p/2)};Sep s=screen(I(p),t,u,I(M));bool hit=false,supported=false;long a=t[0].get_si(),b=t[1].get_si(),c=t[2].get_si(),d=u[0].get_si(),e=u[1].get_si(),f=u[2].get_si();auto md=[&](long z){z%=p;return z<0?z+p:z;};for(long S=0;S<=3*M;S++)for(long V=0;V<=9*M*M;V++)for(long T=0;T<=3*M*M;T++)for(long U=0;U<=M*M*M;U++){hit|=md(T-a*V-b*S-c)==0&&md(U-d*V-e*S-f)==0;tuples++;}for(long x=0;x<=M;x++)for(long y=x;y<=M;y++)for(long z=y;z<=M;z++){long S=x+y+z,T=x*y+x*z+y*z,U=x*y*z;supported|=md(T-a*S*S-b*S-c)==0&&md(U-d*S*S-e*S-f)==0;roots++;}need(!(s.closed&&hit)&&!(s.closed&&supported),"zero false exclusions against independent four-box/root oracle");positive+=supported;maps++;if(s.closed){closed++;if(comma)certs<<',';comma=true;emitcert(certs,I(p),t,u,I(M),s);}}
need(closed&&positive,"nonvacuous rejection/positive controls");std::cout<<"{\"schema\":\"scientific_result_v1\",\"experiment_id\":\""<<id<<"\",\"status\":\"passed\",\"summary\":\"Dual certificates passed independent small box and root-multiset oracles.\",\"evidence\":{\"maps\":"<<maps<<",\"independent_box_tuples\":"<<tuples<<",\"independent_root_multisets\":"<<roots<<",\"positive_maps\":"<<positive<<",\"closed_maps\":"<<closed<<",\"false_exclusions\":0,\"certificates\":["<<certs.str()<<"],\"original_root_count_exact\":null,\"complete_global_root_search\":false,\"qualified_speedup\":null,\"release_gate_claim\":false},\"next_actions\":[\"Run the separately frozen actual NIST profile only after these controls pass.\"]}\n";}

struct EP{Pt p;bool inf=false;};
EP ecadd(const Field&f,I a,EP P,EP R){if(P.inf)return R;if(R.inf)return P;auto x=P.p,y=R.p;if(x.x==y.x&&f.mod(x.y+y.y)==0)return{{0,0},true};I m=x.x==y.x?f.mod((3*x.x*x.x+a)*f.inv(2*x.y)):f.mod((y.y-x.y)*f.inv(y.x-x.x));I xx=f.mod(m*m-x.x-y.x);return{{xx,f.mod(m*(x.x-xx)-x.y)},false};}
std::vector<Pt> bases(const Field&f,I a,I b){std::vector<Pt>v;for(unsigned x=0;x<4096&&v.size()<6;x++){I y;if(f.sqrt_ts(f.mod(I(x)*x*x+a*x+b),y)){I neg=f.mod(-y);if(neg<y)y=neg;v.push_back({I(x),y});}}need(v.size()==6,"six distinct anchor abscissae");return v;}
std::pair<Quad,Quad> fits(const Field&f,I a,I b,Pt z,Pt x,Pt y,I h){auto l=line(f,z,x,y,h);I kap=f.mod(-2*l.A);need(kap!=0,"positive anchor sum slope");I delta=f.mod(h*h-z.x-2*l.B-x.x-y.x),ik=f.inv(kap);auto at=[&](I S){return residual(f,a,b,z,x,y,h,l,f.mod((S-delta)*ik));};auto c0=at(0),c1=at(1),c2=at(2);Quad t{},u{};for(int j=0;j<2;j++){I v0=j?f.mod(-c0[0]):c0[1],v1=j?f.mod(-c1[0]):c1[1],v2=j?f.mod(-c2[0]):c2[1];Quad q{f.mod((v2-2*v1+v0)*f.inv(2)),0,v0};q[1]=f.mod(v1-q[0]-q[2]);if(j)u=q;else t=q;}return{t,u};}
void ptjson(std::ostream&o,Pt p){o<<"[\""<<p.x<<"\",\""<<p.y<<"\"]";}
void positive(const std::string&input){std::ifstream in(input);need(bool(in),"positive input");std::string name;int bits,dim;bool comma=false;unsigned count=0;std::ostringstream out;out<<"{\"schema\":\"planted-nist-positive-cases/v1\",\"label\":\"PLANTED_NOT_BENCHMARK\",\"cases\":[";while(in>>name>>bits>>dim){I p,a,b,zx,zy;in>>p>>a>>b>>zx>>zy;Field f{p};I M=(I(1)<<dim)-1;auto pts=bases(f,a,b);bool done=false;for(unsigned attempt=0;attempt<3&&!done;attempt++){Pt A=pts[attempt],B=pts[attempt+1],C=pts[attempt+2],D=pts[attempt+3];std::array<Pt,5>src{A,A,B,C,D};EP sum{{0,0},true};for(auto q:src)sum=ecadd(f,a,sum,{q,false});if(sum.inf)continue;Pt z{sum.p.x,f.mod(-sum.p.y)};if(z.x<=M)continue;std::array<Pt,5>eq{A,B,C,D,z};std::array<std::array<I,6>,5>mat{};for(int i=0;i<5;i++){auto q=eq[i];mat[i]={f.mod(q.x*q.x),q.x,1,f.mod(q.x*q.y),q.y,f.mod(-q.x*q.x*q.x)};}for(int j=0;j<5;j++){int k=j;while(k<5&&mat[k][j]==0)k++;need(k<5,"positive monic function linear solve");std::swap(mat[k],mat[j]);I inv=f.inv(mat[j][j]);for(int t=j;t<6;t++)mat[j][t]=f.mod(mat[j][t]*inv);for(int i=0;i<5;i++)if(i!=j){I m=mat[i][j];for(int t=j;t<6;t++)mat[i][t]=f.mod(mat[i][t]-m*mat[j][t]);}}I rr=mat[0][5],ss=mat[1][5],tt=mat[2][5],h=mat[3][5],k=mat[4][5];for(auto q:eq)need(f.mod(q.x*q.x*q.x+rr*q.x*q.x+ss*q.x+tt+(h*q.x+k)*q.y)==0,"all positive function vanishings");need(A.y!=0,"positive tangent denominator");I tangent=f.mod(3*A.x*A.x+2*rr*A.x+ss+h*A.y+(h*A.x+k)*(3*A.x*A.x+a)*f.inv(2*A.y));need(tangent==0,"positive repeated tangent");Poly P{tt,ss,rr,1},N=mul(f,P,P),FQ=mul(f,Poly{b,a,0,1},mul(f,Poly{k,h},Poly{k,h}));for(unsigned j=0;j<FQ.size();j++)N[j]=f.mod(N[j]-FQ[j]);Poly H=divide(f,N,z.x),expected{1};for(auto q:src)expected=mul(f,expected,Poly{f.mod(-q.x),1});need(H==expected,"positive entire quintic norm factorization");std::array<Pt,3>others{B,C,D};Pt x{},y{};bool found=false;for(int i=0;i<3&&!found;i++)for(int j=i+1;j<3&&!found;j++){auto l=line(f,z,others[i],others[j],h);if(l.A!=0){x=others[i];y=others[j];found=true;}}need(found,"positive unit slope anchor pair");auto q=fits(f,a,b,z,x,y,h);auto sep=screen(p,q.first,q.second,M);need(!sep.closed,"positive true root must survive dual screen");std::vector<I>roots;bool usedx=false,usedy=false;for(auto v:src){if(!usedx&&v.x==x.x){usedx=true;continue;}if(!usedy&&v.x==y.x){usedy=true;continue;}roots.push_back(v.x);}need(roots.size()==3,"three residual roots");std::sort(roots.begin(),roots.end());if(comma)out<<',';comma=true;out<<"{\"public\":{\"field\":\""<<name<<"\",\"p\":\""<<p<<"\",\"M\":\""<<M<<"\",\"dimension\":"<<dim<<",\"curve_a\":\""<<a<<"\",\"curve_b\":\""<<b<<"\",\"target\":";ptjson(out,z);out<<",\"anchor_x\":";ptjson(out,x);out<<",\"anchor_y\":";ptjson(out,y);out<<",\"h\":\""<<h<<"\",\"T\":";quad(out,q.first);out<<",\"U\":";quad(out,q.second);out<<"},\"expected\":{\"k\":\""<<k<<"\",\"r\":\""<<rr<<"\",\"s\":\""<<ss<<"\",\"t\":\""<<tt<<"\",\"residual_roots\":[";for(int j=0;j<3;j++){if(j)out<<',';out<<'"'<<roots[j]<<'"';}out<<"],\"source_points\":[";for(int j=0;j<5;j++){if(j)out<<',';ptjson(out,src[j]);}out<<"]}}";done=true;count++;}need(done,"fixed positive pattern selection");}need(count==5,"all five planted controls");out<<"]}";std::cout<<out.str()<<'\n';}

int main(int argc,char**argv){auto started=Clock::now();try{need(argc>=3,"id mode");std::string id=argv[1],mode=argv[2];if(mode=="controls"){controls(id);return 0;}if(mode=="positive"){need(argc==4,"positive input");positive(argv[3]);return 0;}need(mode=="profile"&&argc==4,"profile input");std::ifstream in(argv[3]);need(bool(in),"input");std::ostringstream records;bool comma=false;unsigned fields=0,lines=0,closed=0,caps=0,totalsteps=0;std::string name;int bits,d;
while(in>>name>>bits>>d){static const std::array<std::string,5>names{"P-192","P-224","P-256","P-384","P-521"};static const std::array<int,5>dims{40,47,53,79,106};need(fields<5&&name==names[fields]&&d==dims[fields],"fixed five fields");I p,a,b,zx,zy;in>>p>>a>>b>>zx>>zy;need(bool(in),"complete field");Field f{p};Pt z{zx,zy};I M=(I(1)<<d)-1;need(3*M<p&&3*M*M<p&&M*M*M<p&&z.x>M&&f.mod(z.y*z.y-z.x*z.x*z.x-a*z.x-b)==0,"actual field/domain/target guards");auto base=bases(f,a,b);std::vector<std::pair<Pt,Pt>>pairs;for(unsigned i=0;i<6;i++)for(unsigned j=i+1;j<6&&pairs.size()<8;j++){unsigned n=pairs.size();Pt x=base[i],y=base[j];if(n&1)x.y=f.mod(-x.y);if((n>>1)&1)y.y=f.mod(-y.y);pairs.push_back({x,y});}need(pairs.size()==8,"eight diverse pairs available");fields++;
for(unsigned pi=0;pi<8;pi++)for(unsigned hi=0;hi<8;hi++){need(std::chrono::duration<double>(Clock::now()-started).count()<65,"native traversal deadline");static const long hg[8]={0,1,-1,2,-2,3,-3,4};I h=f.mod(I(hg[hi]));auto x=pairs[pi].first,y=pairs[pi].second;Line l=line(f,z,x,y,h);I kap=f.mod(-2*l.A),delta=f.mod(h*h-z.x-2*l.B-x.x-y.x);bool isclosed=false;Sep sep;Quad t{},u{};I total=3*M+1;if(kap==0){total=p;}else{I ik=f.inv(kap);auto at=[&](I S){return residual(f,a,b,z,x,y,h,l,f.mod((S-delta)*ik));};auto fit=[&](bool product){auto c0=at(0),c1=at(1),c2=at(2);I f0=product?f.mod(-c0[0]):c0[1],f1=product?f.mod(-c1[0]):c1[1],f2=product?f.mod(-c2[0]):c2[1];return Quad{f.mod((f2-2*f1+f0)*f.inv(2)),0,f0};};t=fit(false);u=fit(true);auto c1=at(1);t[1]=f.mod(c1[1]-t[2]-t[0]);u[1]=f.mod(-c1[0]-u[2]-u[0]);for(I S:{I(0),I(1),I(2),I(3),M,I(3*M)}){auto C=at(S);need(f.mod(qe(t,S))==C[1]&&f.mod(qe(u,S))==f.mod(-C[0]),"quadratic literal residual checks");}sep=screen(p,t,u,M);isclosed=sep.closed;caps+=!sep.reduced;totalsteps+=sep.steps;}
if(comma)records<<',';comma=true;records<<"{\"field\":\""<<name<<"\",\"curve_a\":\""<<a<<"\",\"curve_b\":\""<<b<<"\",\"target\":[\""<<z.x<<"\",\""<<z.y<<"\"],\"anchor_x\":[\""<<x.x<<"\",\""<<x.y<<"\"],\"anchor_y\":[\""<<y.x<<"\",\""<<y.y<<"\"],\"h\":\""<<h<<"\",\"pair\":"<<pi<<",\"h_index\":"<<hi<<",\"A0\":"<<(kap==0?"true":"false")<<",\"declared_parameter_count\":\""<<total<<"\",\"closed\":"<<(isclosed?"true":"false")<<",\"unresolved_parameter_count\":\""<<(isclosed?I(0):total)<<"\",\"steps\":"<<sep.steps<<",\"certificate\":";if(isclosed)emitcert(records,p,t,u,M,sep);else records<<"null";records<<'}';lines++;closed+=isclosed;}}
need(fields==5&&lines==320,"complete320-line profile");auto render=[&](bool exact){std::ostringstream out;out<<"{\"schema\":\"scientific_result_v1\",\"experiment_id\":\""<<id<<"\",\"status\":\""<<(exact?"passed":"inconclusive")<<"\",\"summary\":\"Exact dual-separator NIST profile with certified rejected whole lines and explicit unresolved mass.\",\"evidence\":{\"bounded_profile_complete\":"<<(exact?"true":"false")<<",\"fields\":"<<fields<<",\"conditional_lines\":"<<lines<<",\"certified_closed_lines\":"<<(exact?std::to_string(closed):"null")<<",\"LLL_capped_lines\":"<<caps<<",\"LLL_total_steps\":"<<totalsteps<<",\"rows\":["<<records.str()<<"],\"original_root_count_exact\":null,\"complete_global_root_search\":false,\"qualified_speedup\":null,\"release_gate_claim\":false},\"next_actions\":[\"Study unresolved cells or expand independently reserved scope; no global root or speedup claim.\"]}";return out.str();};std::string text=render(true);if(std::chrono::duration<double>(Clock::now()-started).count()>=80)text=render(false);need(std::chrono::duration<double>(Clock::now()-started).count()<82,"native final serialization deadline");std::cout<<text<<'\n';}catch(std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
